import json, re
def toks(t):
    return re.findall(r"[a-z0-9]+", t.lower())
def headphrase(desc):
    segs = [s.strip() for s in desc.split(',') if s.strip()]
    state = {'canned','cooked','dried','fresh','frozen','pickled','raw','roasted','salted','smoked','toasted','unsalted','dry','grated','crushed','chopped','sliced','minced','ground','powdered','flaked','shredded','sliced','thin','thick','whole','soft','firm','ripe','mature','young','baby','small','large','medium','extra','light','reduced','fat','full','skim','low','sweet','unsweetened','plain','natural','organic','fresh'}
    out=[]
    for s in segs:
        st = toks(s)
        if st and all(w in state for w in st):
            break
        out.extend(st)
    return out
rows=[]
with open('Resources/features/f-428/runs/P12.7/base-debug.jsonl') as f:
    for line in f:
        r=json.loads(line)
        if r['auto'] and not r['correct']:
            exp=r['expectedDescriptions'][0] if r['expectedDescriptions'] else ''
            act=r['actualDescriptions'][0] if r['actualDescriptions'] else ''
            rows.append((r['rawText'], exp, act, r['atoms'][0]['parsedName'], r['atoms'][0]['path'], r['atoms'][0]['reused']))
print(len(rows))
for raw,exp,act,pn,path,reused in rows:
    print(f"{raw!r:55} | key={exp!r:50} | act={act!r:50} | pn={pn!r:18} | {path}/{reused}")
    print(f"   keyHead={headphrase(exp)} actHead={headphrase(act)}")
EOF","i":"Prototyping head-phrase extraction on all 57 debug auto-wrong lines"}

