{"content":"using LetUsCook.AutoWrongCensus.HostedServices;
using LetUsCook.AutoWrongCensus.Options;

using Microsoft.Extensions.DependencyInjection;

namespace LetUsCook.AutoWrongCensus;

/// <summary>
/// The console entry point of the auto-wrong census CLI (F-428 P12.13). <see cref="Program"/> is a
/// one-line delegation to this class so tests can run the exact same host path with captured
/// writers.
/// </summary>
public static class AutoWrongCensusCli
{
	/// <summary>
	/// Runs the CLI. <paramref name="output"/>/<paramref name="error"/> default to the console
	/// streams; tests pass their own to capture the TSV byte-for-byte.
	/// </summary>
	/// <param name="args">The command line arguments.</param>
	/// <param name="output">The TSV output stream. Defaults to <see cref="System.Console.Out"/>.</param>
	/// <param name="error">The summary/error stream. Defaults to <see cref="System.Console.Error"/>.</param>
	/// <returns>The process exit code: 0 on success, 1 on a missing file, a refused set, or a bad invocation.</returns>
	public static async Task<int> RunAsync(string[] args, TextWriter? output = null, TextWriter? error = null)
	{
		if (Array.Exists(args, a => a.Equals("--help", StringComparison.OrdinalIgnoreCase) || a.Equals("-h", StringComparison.OrdinalIgnoreCase)))
		{
			AutoWrongCensusUsage.Print();
			return 0;
		}

		var builder = AutoWrongCensusHostBuilderFactory.Create(args, output, error);
		var host = builder.Build();

		// Resolve BEFORE RunAsync(): RunAsync disposes the provider on shutdown.
		var hostedService = host.Services.GetRequiredService<AutoWrongCensusHostedService>();
		await host.RunAsync().ConfigureAwait(false);
		return hostedService.ExitCode;
	}
}
