namespace LetUsCook.AutoWrongCensus.Models;

/// <summary>
/// One HoldoutGate trace line (the <c>base-{debug,batch}.jsonl</c> schema), projected to the fields the
/// census reads. Unknown fields are ignored; the census never writes back.
/// </summary>
public sealed record TraceLine
{
	/// <summary>The raw recipe line as written.</summary>
	[JsonPropertyName("rawText")]
	public string RawText { get; init; } = string.Empty;

	/// <summary>The holdout row id (e.g. <c>debug:recipe-slug</c>).</summary>
	[JsonPropertyName("holdoutId")]
	public string HoldoutId { get; init; } = string.Empty;

	/// <summary>The line's index within the recipe.</summary>
	[JsonPropertyName("lineIndex")]
	public int LineIndex { get; init; }

	/// <summary>The measured set: <c>debug</c> or <c>batch</c>; anything else is refused (D-029).</summary>
	[JsonPropertyName("set")]
	public string Set { get; init; } = string.Empty;

	/// <summary>Whether the line shipped to the household without review.</summary>
	[JsonPropertyName("auto")]
	public bool Auto { get; init; }

	/// <summary>Whether the accepted row is the labelled (key) row.</summary>
	[JsonPropertyName("correct")]
	public bool Correct { get; init; }

	/// <summary>The labelled (key) row descriptions; empty for an unlabelled line.</summary>
	[JsonPropertyName("expectedDescriptions")]
	public IReadOnlyList<string> ExpectedDescriptions { get; init; } = [];

	/// <summary>The labelled (key) row dataset tiers, parallel to <see cref="ExpectedDescriptions"/>.</summary>
	[JsonPropertyName("expectedDataTypes")]
	public IReadOnlyList<string> ExpectedDataTypes { get; init; } = [];

	/// <summary>The accepted row descriptions; empty when nothing was accepted.</summary>
	[JsonPropertyName("actualDescriptions")]
	public IReadOnlyList<string> ActualDescriptions { get; init; } = [];

	/// <summary>The accepted row dataset tiers, parallel to <see cref="ActualDescriptions"/>.</summary>
	[JsonPropertyName("actualDataTypes")]
	public IReadOnlyList<string> ActualDataTypes { get; init; } = [];

	/// <summary>The per-atom pipeline decisions.</summary>
	[JsonPropertyName("atoms")]
	public IReadOnlyList<TraceAtom> Atoms { get; init; } = [];
}

/// <summary>One atom's pipeline decision inside a <see cref="TraceLine"/>.</summary>
public sealed record TraceAtom
{
	/// <summary>The atom text handed to the resolver.</summary>
	[JsonPropertyName("text")]
	public string Text { get; init; } = string.Empty;

	/// <summary><c>accepted</c>, <c>deferred</c>, or <c>rejected</c>.</summary>
	[JsonPropertyName("outcome")]
	public string Outcome { get; init; } = string.Empty;

	/// <summary>The linked ingredient master's slug, when one was minted.</summary>
	[JsonPropertyName("linkedIngredientId")]
	public string? LinkedIngredientId { get; init; }

	/// <summary>The parsed ingredient name.</summary>
	[JsonPropertyName("parsedName")]
	public string ParsedName { get; init; } = string.Empty;

	/// <summary>Whether the accepted row was reused from an existing master.</summary>
	[JsonPropertyName("reused")]
	public bool Reused { get; init; }

	/// <summary>The decision path: <c>ranker</c>, <c>override</c>, or <c>curated</c>.</summary>
	[JsonPropertyName("path")]
	public string Path { get; init; } = string.Empty;
}
