{"content":"using System.Text.Json;

using LetUsCook.Fdc.Lexicon;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// The key set of <c>src/LetUsCook.Fdc/Lexicon/Resources/exact-overrides.json</c>, read from the
/// embedded resource of the production assembly — the same bytes the matcher ships, so the census
/// never drifts from the file it reports on.
/// </summary>
public sealed class ExactOverrideKeyIndex
{
	private readonly FrozenSet<string> _keys;

	/// <summary>Loads the embedded <c>exact-overrides.json</c> keys (case-insensitive).</summary>
	public ExactOverrideKeyIndex()
	{
		var assembly = typeof(FdcLexicon).Assembly;
		var name = assembly.GetManifestResourceNames().Single(n => n.EndsWith("exact-overrides.json", StringComparison.Ordinal));
		using var stream = assembly.GetManifestResourceStream(name)
			?? throw new InvalidOperationException($"Embedded resource '{name}' not found.");
		using var reader = new StreamReader(stream);
		var keys = JsonSerializer.Deserialize<Dictionary<string, JsonElement>>(reader.ReadToEnd(), new JsonSerializerOptions(JsonSerializerDefaults.Web))
			?? throw new InvalidOperationException("exact-overrides.json was empty.");
		_keys = keys.Keys.ToFrozenSet(StringComparer.OrdinalIgnoreCase);
	}

	/// <summary>Whether the given key is in <c>exact-overrides.json</c>.</summary>
	/// <param name="key">The key to test.</param>
	public bool Contains(string key) => _keys.Contains(key);
}
