{"content":"using System.Text.RegularExpressions;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.Fdc;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Matching;
using LetUsCook.Fdc.Parsing;
using LetUsCook.Fdc.Resolver;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// F-428 P12.13: classifies one auto-wrong trace line on two axes — the relation between the
/// accepted row and the labelled (key) row, and the decision site. Every comparison goes through
/// the production helpers (D-014): <see cref="FdcNormalizer.NormalizeToTokens"/>,
/// <see cref="FdcMatcher.ExtractCandidateState"/>, <see cref="FdcMatcher.ExtractCandidateSatisfiers"/>,
/// <see cref="FdcDescriptionParser.Parse"/>, <see cref="IngredientLineResolver.SingularizeToken"/> and
/// <see cref="IngredientLineResolver.ShouldReuse"/> — never a copy of their logic.
/// </summary>
public sealed partial class AutoWrongClassifier
{
	/// <summary>Relation: the key row is empty.</summary>
	public const string NoLabel = "no-label";

	/// <summary>Relation: a can/jar unit in the raw text, the key row is canned, the accepted row is not.</summary>
	public const string PackUnitState = "pack-unit-state";

	/// <summary>Relation: the key head phrase has two or more words and the parsed name is only its first word.</summary>
	public const string CompoundHeadLost = "compound-head-lost";

	/// <summary>Relation: the head terms agree and the state masks differ.</summary>
	public const string StateMismatch = "state-mismatch";

	/// <summary>Relation: head and state agree and the dataset tier differs.</summary>
	public const string RowChoiceTier = "row-choice-tier";

	/// <summary>Relation: head and state agree, the tier agrees, and only the qualifiers differ.</summary>
	public const string SameHeadOtherQualifier = "same-head-other-qualifier";

	/// <summary>Relation: the head terms differ.</summary>
	public const string SiblingFood = "sibling-food";

	/// <summary>Relation: nothing above held, or a field a check needed was missing.</summary>
	public const string Other = "other";

	/// <summary>Site: the line reused an existing row through the ranker path.</summary>
	public const string SiteReuse = "reuse";

	/// <summary>Site: the line went through the override path.</summary>
	public const string SiteOverride = "override";

	/// <summary>Site: the line went through the curated catalogue.</summary>
	public const string SiteCurated = "curated";

	/// <summary>Site: the ranker picked the row without reuse.</summary>
	public const string SiteRanker = "ranker";

	private readonly FdcNormalizer _normalizer;
	private readonly ExactOverrideKeyIndex _overrideKeys;

	// Reused for the per-token state probe; the classifier is single-threaded (one runner, sequential lines).
	private readonly string?[] _singleTokenScratch = new string[1];

	/// <summary>Creates the classifier.</summary>
	/// <param name="normalizer">The production normalizer.</param>
	/// <param name="overrideKeys">The <c>exact-overrides.json</c> key index.</param>
	public AutoWrongClassifier(FdcNormalizer normalizer, ExactOverrideKeyIndex overrideKeys)
	{
		_normalizer = normalizer ?? throw new ArgumentNullException(nameof(normalizer));
		_overrideKeys = overrideKeys ?? throw new ArgumentNullException(nameof(overrideKeys));
	}

	[GeneratedRegex(@"\b(?:cans?|jars?)\b", RegexOptions.IgnoreCase)]
	private static partial Regex PackUnitRegex();

	/// <summary>
	/// Classifies one auto-wrong line. The first relation that holds wins, in the brief's order:
	/// no-label, pack-unit-state, compound-head-lost, state-mismatch, row-choice-tier,
	/// same-head-other-qualifier, sibling-food, other.
	/// </summary>
	/// <param name="line">The trace line (<c>auto == true &amp;&amp; correct == false</c>).</param>
	/// <returns>The classification; <see cref="ClassificationResult.Site"/> is empty when the atom path is unknown.</returns>
	public ClassificationResult Classify(TraceLine line)
	{
		ArgumentNullException.ThrowIfNull(line);

		var keyDesc = First(line.ExpectedDescriptions);
		var acceptedDesc = First(line.ActualDescriptions);
		var keyTier = First(line.ExpectedDataTypes);
		var acceptedTier = First(line.ActualDataTypes);
		var atom = line.Atoms.FirstOrDefault(a => a.Outcome == "accepted") ?? line.Atoms.FirstOrDefault();

		var result = new ClassificationResult
		{
			HoldoutId = line.HoldoutId,
			LineIndex = line.LineIndex,
			Set = line.Set,
			AcceptedTier = acceptedTier,
			KeyTier = keyTier,
			ParsedName = atom?.ParsedName ?? string.Empty,
			AcceptedDesc = acceptedDesc,
			KeyDesc = keyDesc,
			RawText = line.RawText,
		};

		result.Site = ClassifySite(atom, line.RawText);
		if (result.Site == string.Empty)
		{
			return result;
		}

		if (string.IsNullOrWhiteSpace(keyDesc))
		{
			result.Relation = NoLabel;
			return result;
		}

		var keyTokens = _normalizer.NormalizeToTokens(keyDesc);
		var acceptedTokens = _normalizer.NormalizeToTokens(acceptedDesc);
		var keyState = CombinedState(keyTokens);
		var acceptedState = CombinedState(acceptedTokens);
		result.KeyState = keyState.ToString();
		result.AcceptedState = acceptedState.ToString();

		var keyHead = SingularPhrase(FdcDescriptionParser.Parse(keyDesc, DatasetOf(keyTier)).HeadTerm);
		var acceptedHead = SingularPhrase(FdcDescriptionParser.Parse(acceptedDesc, DatasetOf(acceptedTier)).HeadTerm);
		result.KeyHead = string.Join(' ', keyHead);

		var parsedNameTokens = SingularPhrase(atom?.ParsedName ?? string.Empty);
		var keyHeadPhrase = KeyHeadPhrase(keyTokens);

		if (PackUnitRegex().IsMatch(line.RawText) && (keyState & FoodState.Canned) != FoodState.None && (acceptedState & FoodState.Canned) == FoodState.None)
		{
			result.Relation = PackUnitState;
			return result;
		}

		if (keyHeadPhrase.Count >= 2 && parsedNameTokens.Count == 1 &&
			string.Equals(parsedNameTokens[0], IngredientLineResolver.SingularizeToken(keyHeadPhrase[0]), StringComparison.OrdinalIgnoreCase))
		{
			result.Relation = CompoundHeadLost;
			return result;
		}

		if (keyHead.SequenceEqual(acceptedHead, StringComparer.OrdinalIgnoreCase))
		{
			if (keyState != acceptedState)
			{
				result.Relation = StateMismatch;
				return result;
			}

			if (string.IsNullOrWhiteSpace(keyTier) || string.IsNullOrWhiteSpace(acceptedTier))
			{
				result.Relation = Other;
				result.MissingField = string.IsNullOrWhiteSpace(keyTier) ? "expectedDataTypes" : "actualDataTypes";
				return result;
			}

			if (!string.Equals(keyTier, acceptedTier, StringComparison.OrdinalIgnoreCase))
			{
				result.Relation = RowChoiceTier;
				return result;
			}

			result.Relation = SameHeadOtherQualifier;
			var keyQualifiers = SingularPhraseSet(FdcDescriptionParser.Parse(keyDesc, DatasetOf(keyTier)).Qualifiers);
			var acceptedQualifiers = SingularPhraseSet(FdcDescriptionParser.Parse(acceptedDesc, DatasetOf(acceptedTier)).Qualifiers);
			result.KeyOnlyQualifiers = keyQualifiers.Except(acceptedQualifiers, StringComparer.OrdinalIgnoreCase).OrderBy(t => t, StringComparer.Ordinal).ToArray();
			result.AcceptedOnlyQualifiers = acceptedQualifiers.Except(keyQualifiers, StringComparer.OrdinalIgnoreCase).OrderBy(t => t, StringComparer.Ordinal).ToArray();
			return result;
		}

		result.Relation = SiblingFood;
		return result;
	}

	/// <summary>
	/// The key head phrase: the key's normalized tokens up to the first word the production state
	/// vocabulary (modifier words, <see cref="FdcMatcher.ExtractCandidateState"/>,
	/// <see cref="FdcMatcher.ExtractCandidateSatisfiers"/>) marks as state. "Bread, crumbs, dry, grated,
	/// plain" is <c>bread crumbs</c>; "Tomatoes, crushed, canned" is <c>tomato</c>.
	/// </summary>
	/// <param name="keyTokens">The key description's normalized tokens.</param>
	/// <returns>The head phrase tokens.</returns>
	public IReadOnlyList<string> KeyHeadPhrase(IReadOnlyList<string> keyTokens)
	{
		var phrase = new List<string>(keyTokens.Count);
		foreach (var token in keyTokens)
		{
			if (CarriesStateToken(token))
			{
				break;
			}

			phrase.Add(token);
		}

		return phrase;
	}

	/// <summary>The production state ∪ satisfiers mask for a token list.</summary>
	/// <param name="tokens">The normalized tokens.</param>
	/// <returns>The combined mask.</returns>
	public static FoodState CombinedState(IReadOnlyList<string> tokens) =>
		FdcMatcher.ExtractCandidateState(tokens) | FdcMatcher.ExtractCandidateSatisfiers(tokens);

	/// <summary>
	/// Whether the resolver's own exact-phrase reuse rule (<see cref="IngredientLineResolver.ShouldReuse"/>)
	/// would link <paramref name="parsedName"/> to <paramref name="linkedIngredientId"/>.
	/// </summary>
	/// <param name="parsedName">The parser name.</param>
	/// <param name="linkedIngredientId">The linked master slug.</param>
	/// <returns>Whether the production rule would reuse.</returns>
	public static bool ProductionShouldReuse(string parsedName, string linkedIngredientId) =>
		IngredientLineResolver.ShouldReuse(IngredientLineParser.ComputeSlug(parsedName), linkedIngredientId);

	/// <summary>
	/// The dataset tier for a trace dataType string; unknown values parse as <see cref="FdcDataset.None"/>
	/// (the curated parse path), which is the safe side for a census.
	/// </summary>
	/// <param name="dataType">The trace dataType string.</param>
	/// <returns>The tier.</returns>
	public static FdcDataset DatasetOf(string dataType) =>
		Enum.TryParse<FdcDataset>(dataType, ignoreCase: true, out var dataset) ? dataset : FdcDataset.None;

	/// <summary>
	/// Folds raw line text the way the override lookup does (FdcMatcher.MatchAsync): lower-cased,
	/// trimmed, content from the first <c>(</c> dropped.
	/// </summary>
	/// <param name="rawText">The raw line text.</param>
	/// <returns>The folded text.</returns>
	public static string NormalizeForOverrideKey(string rawText)
	{
#pragma warning disable CA1308 // Reason: parity with FdcMatcher.MatchAsync's override lookup folding.
		var lowered = rawText.Trim().ToLowerInvariant();
#pragma warning restore CA1308
		var paren = lowered.IndexOf('(', StringComparison.Ordinal);
		return (paren >= 0 ? lowered[..paren] : lowered).Trim();
	}

	/// <summary>
	/// The decision site from the atom: <c>override</c>/<c>curated</c> by path, <c>reuse</c> when the
	/// ranker path reused a row, <c>ranker</c> otherwise. Empty when the path is unknown.
	/// </summary>
	/// <param name="atom">The trace atom, or null.</param>
	/// <param name="rawText">The raw line text (for the override key check).</param>
	/// <returns>The site, or empty.</returns>
	public string ClassifySite(TraceAtom? atom, string rawText)
	{
		if (atom is null)
		{
			return string.Empty;
		}

		return atom.Path switch
		{
			"override" => SiteOverride,
			"curated" => SiteCurated,
			"ranker" => atom.Reused ? SiteReuse : SiteRanker,
			_ => string.Empty,
		};
	}

	/// <summary>
	/// Whether the normalized raw text is a key in <c>exact-overrides.json</c>; <c>yes</c>/<c>no</c> for
	/// override-site lines, empty elsewhere.
	/// </summary>
	/// <param name="site">The classified site.</param>
	/// <param name="rawText">The raw line text.</param>
	/// <returns>The overrideKey column value.</returns>
	public string OverrideKeyColumn(string site, string rawText)
	{
		if (site != SiteOverride)
		{
			return string.Empty;
		}

		return _overrideKeys.IsKey(NormalizeForOverrideKey(rawText)) ? "yes" : "no";
	}

	private static string First(IReadOnlyList<string> values) =>
		values.Count > 0 && !string.IsNullOrWhiteSpace(values[0]) ? values[0] : string.Empty;

	private IReadOnlyList<string> SingularPhrase(string? text) =>
		_normalizer.NormalizeToTokens(text).Select(IngredientLineResolver.SingularizeToken).ToArray();

	private HashSet<string> SingularPhraseSet(IReadOnlyList<string> tokens) =>
		tokens.Select(IngredientLineResolver.SingularizeToken).ToHashSet(StringComparer.OrdinalIgnoreCase);

	private bool CarriesStateToken(string token)
	{
		_singleTokenScratch[0] = token;
		return FdcLexicon.Default.ModifierWords.Contains(token)
			|| FdcMatcher.ExtractCandidateState(_singleTokenScratch) != FoodState.None
			|| FdcMatcher.ExtractCandidateSatisfiers(_singleTokenScratch) != FoodState.None;
	}
}
