{"content":"using System.Globalization;
using System.Text.Json;
using System.Text.Json.Serialization;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.AutoWrongCensus.Options;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// Runs the census over one HoldoutGate trace (or the P12.7 window pairs) and writes the TSV to
/// <see cref="AutoWrongCensusOptions"/>'s sinks. Exit code: 0 on success, 1 on a missing file,
/// a refused set (D-029), or a malformed invocation.
/// </summary>
public sealed class AutoWrongCensusRunner(
	IOptions<AutoWrongCensusOptions> options,
	AutoWrongClassifier classifier,
	System.IO.TextWriter output,
	System.IO.TextWriter error)
{
	/// <summary>Trace sets the census may read; anything else is refused (D-029).</summary>
	public static readonly FrozenSet<string> AllowedSets = FrozenSet.ToFrozenSet(["debug", "batch"], StringComparer.Ordinal);

	private static readonly JsonSerializerOptions JsonOptions = new(JsonSerializerDefaults.Web);

	/// <summary>Runs the configured subcommand.</summary>
	/// <param name="cancellationToken">Cancellation token.</param>
	/// <returns>0 on success, 1 on failure.</returns>
	public async Task<int> RunAsync(CancellationToken cancellationToken)
	{
		var opts = options.Value;
		if (opts.Command == CommandLineArgumentParser.CensusCommand)
		{
			return await RunCensusAsync(opts.TracePath, cancellationToken).ConfigureAwait(false);
		}

		if (opts.Command == CommandLineArgumentParser.PairsCommand)
		{
			return await RunPairsAsync(opts.CensusTsvPath, opts.TracePath, cancellationToken).ConfigureAwait(false);
		}

		Options.AutoWrongCensusUsage.Print();
		error.WriteLine("error: unusable arguments; expected 'census <trace.jsonl>' or 'pairs <census.tsv> <trace.jsonl>'");
		return 1;
	}

	private async Task<int> RunCensusAsync(string tracePath, CancellationToken cancellationToken)
	{
		var lines = await ReadTraceAsync(tracePath, error).ConfigureAwait(false);
		if (lines is null)
		{
			return 1;
		}

		var refused = lines.FirstOrDefault(l => !AllowedSets.Contains(l.Set));
		if (refused is not null)
		{
			error.WriteLine($"refused: trace record {refused.HoldoutId}#{refused.LineIndex} has set '{refused.Set}'; the census reads debug/batch only (D-029)");
			return 1;
		}

		var autoWrong = lines.Where(l => l.Auto && !l.Correct).ToList();
		var results = new List<ClassificationResult>(autoWrong.Count);
		var unknownSite = 0;
		foreach (var line in autoWrong)
		{
			var result = classifier.Classify(line);
			if (result.Site.Length == 0)
			{
				unknownSite++;
				error.WriteLine($"error: {line.HoldoutId}#{line.LineIndex} has unknown atom path '{line.Atoms.FirstOrDefault()?.Path ?? "<none>"}'; cannot classify the site");
				continue;
			}

			results.Add(result);
		}

		WriteCensusTsv(results, output);
		WriteSummary(results, autoWrong.Count, unknownSite, error);
		return unknownSite == 0 ? 0 : 1;
	}

	private async Task<int> RunPairsAsync(string censusTsvPath, string tracePath, CancellationToken cancellationToken)
	{
		if (!File.Exists(censusTsvPath))
		{
			error.WriteLine($"error: census TSV not found at '{censusTsvPath}'");
			return 1;
		}

		var lines = await ReadTraceAsync(tracePath, error).ConfigureAwait(false);
		if (lines is null)
		{
			return 1;
		}

		var refused = lines.FirstOrDefault(l => !AllowedSets.Contains(l.Set));
		if (refused is not null)
		{
			error.WriteLine($"refused: trace record {refused.HoldoutId}#{refused.LineIndex} has set '{refused.Set}'; the census reads debug/batch only (D-029)");
			return 1;
		}

		var windowRows = ReadWindowRows(censusTsvPath, error);
		if (windowRows is null)
		{
			return 1;
		}

		var byKey = lines.ToDictionary(l => (l.HoldoutId, l.LineIndex));
		output.WriteLine("holdoutId\tlineIndex\tparsedNameHead\tkeyHead\trawText");
		var emitted = 0;
		foreach (var (holdoutId, lineIndex) in windowRows)
		{
			if (!byKey.TryGetValue((holdoutId, lineIndex), out var line))
			{
				error.WriteLine($"warning: census row {holdoutId}#{lineIndex} not found in the trace");
				continue;
			}

			var atom = line.Atoms.FirstOrDefault(a => a.Outcome.Equals("accepted", StringComparison.OrdinalIgnoreCase)) ?? line.Atoms.FirstOrDefault();
			var parsedNameHead = string.Join(' ', classifier.KeyHeadPhrase(classifier.SingularTokens(classifier.Normalizer, atom?.ParsedName ?? string.Empty)));
			var keyHead = string.Join(' ', classifier.KeyHeadPhrase(classifier.Normalizer.NormalizeToTokens(First(line.ExpectedDescriptions))));
			output.WriteLine($"{line.HoldoutId}\t{line.LineIndex}\t{parsedNameHead}\t{keyHead}\t{line.RawText}");
			emitted++;
		}

		error.WriteLine($"pairs: {emitted} of {windowRows.Count} window compound/other rows emitted");
		return 0;
	}

	private static async Task<List<TraceLine>?> ReadTraceAsync(string tracePath, System.IO.TextWriter error)
	{
		if (!File.Exists(tracePath))
		{
			error.WriteLine($"error: trace not found at '{tracePath}'");
			return null;
		}

		var lines = new List<TraceLine>();
		await foreach (var line in FileLinesAsync(tracePath).ConfigureAwait(false))
		{
			if (line.Length == 0)
			{
				continue;
			}

			try
			{
				lines.Add(JsonSerializer.Deserialize<TraceLine>(line, JsonOptions)
					?? throw new InvalidOperationException("trace line deserialized to null"));
			}
			catch (JsonException ex)
			{
				error.WriteLine($"error: trace line is not valid JSON: {ex.Message}");
				return null;
			}
		}

		return lines;
	}

	private static async IAsyncEnumerable<string> FileLinesAsync(string path)
	{
		await using var reader = new StreamReader(path);
		string? line;
		while ((line = await reader.ReadLineAsync().ConfigureAwait(false)) is not null)
		{
			yield return line;
		}
	}

	private static List<(string HoldoutId, int LineIndex)>? ReadWindowRows(string censusTsvPath, System.IO.TextWriter error)
	{
		var rows = new List<(string, int)>();
		var headerSeen = false;
		int holdoutCol = -1, lineCol = -1, blockerCol = -1, routeCol = -1;

		foreach (var raw in File.ReadLines(censusTsvPath))
		{
			var cells = raw.Split('\t');
			if (!headerSeen)
			{
				headerSeen = true;
				for (var i = 0; i < cells.Length; i++)
				{
					switch (cells[i])
					{
						case "holdoutId": holdoutCol = i; break;
						case "lineIndex": lineCol = i; break;
						case "blocker": blockerCol = i; break;
						case "route": routeCol = i; break;
					}
				}

				if (holdoutCol < 0 || lineCol < 0 || blockerCol < 0 || routeCol < 0)
				{
					error.WriteLine("error: census TSV is missing holdoutId/lineIndex/blocker/route columns");
					return null;
				}

				continue;
			}

			if (cells.Length <= Math.Max(holdoutCol, Math.Max(lineCol, Math.Max(blockerCol, routeCol))))
			{
				continue;
			}

			if (cells[blockerCol] == "window" && (cells[routeCol] == "compound" || cells[routeCol] == "other")
				&& int.TryParse(cells[lineCol], NumberStyles.Integer, CultureInfo.InvariantCulture, out var lineIndex))
			{
				rows.Add((cells[holdoutCol], lineIndex));
			}
		}

		return rows;
	}

	private static void WriteCensusTsv(IReadOnlyList<ClassificationResult> results, System.IO.TextWriter output)
	{
		output.WriteLine("holdoutId\tlineIndex\tset\trelation\tsite\toverrideKey\tacceptedTier\tkeyTier\tacceptedState\tkeyState\tparsedName\tkeyHead\tacceptedDesc\tkeyDesc\trawText");
		foreach (var r in results)
		{
			output.WriteLine(string.Join('\t',
				Sanitize(r.HoldoutId),
				r.LineIndex.ToString(CultureInfo.InvariantCulture),
				Sanitize(r.Set),
				r.Relation,
				r.Site,
				r.OverrideKey,
				Sanitize(r.AcceptedTier),
				Sanitize(r.KeyTier),
				r.AcceptedState,
				r.KeyState,
				Sanitize(r.ParsedName),
				Sanitize(r.KeyHead),
				Sanitize(r.AcceptedDesc),
				Sanitize(r.KeyDesc),
				Sanitize(r.RawText)));
		}
	}

	private static void WriteSummary(IReadOnlyList<ClassificationResult> results, int autoWrongCount, int unknownSite, System.IO.TextWriter error)
	{
		var set = results.Count > 0 ? results[0].Set : string.Empty;
		error.WriteLine($"autoWrongCensus set={set} autoWrongLines={autoWrongCount} classified={results.Count} unknownSite={unknownSite}");

		var matrix = results
			.GroupBy(r => (r.Relation, r.Site))
			.Select(g => (g.Key.Relation, g.Key.Site, g.Count()))
			.OrderBy(t => t.Relation, StringComparer.Ordinal)
			.ThenBy(t => t.Site, StringComparer.Ordinal);
		error.WriteLine("relation\tsite\tcount");
		foreach (var (relation, site, count) in matrix)
		{
			error.WriteLine($"{relation}\t{site}\t{count}");
		}

		var other = results.Count(r => r.Relation == AutoWrongClassifier.RelationOther);
		var otherRate = results.Count > 0 ? other * 100.0 / results.Count : 0.0;
		error.WriteLine($"other rate: {other}/{results.Count} ({otherRate:0.0}%)");

		var missing = results.Where(r => r.MissingField is not null).GroupBy(r => r.MissingField).Select(g => $"{g.Key}={g.Count()}");
		error.WriteLine($"missing fields: {(missing.Any() ? string.Join(' ', missing) : "none")}");

		var overrideLines = results.Where(r => r.Site == AutoWrongClassifier.SiteOverride).ToList();
		var overrideHits = overrideLines.Count(r => r.OverrideKey == "yes");
		error.WriteLine($"override-site lines: {overrideLines.Count}, normalized rawText is an exact-overrides.json key: {overrideHits}");

		var reuseLines = results.Where(r => r.Site == AutoWrongClassifier.SiteReuse).ToList();
		var reuseNameMismatch = 0;
		foreach (var r in reuseLines)
		{
			var line = r;
			if (line.ParsedName.Length == 0)
			{
				continue;
			}

			var slug = LetUsCook.Fdc.Parsing.IngredientLineParser.ComputeSlug(line.ParsedName);
			if (slug.Length > 0 && !string.IsNullOrEmpty(line.LinkedIngredientId)
				&& !LetUsCook.Fdc.Resolver.IngredientLineResolver.ShouldReuse(slug, line.LinkedIngredientId!))
			{
				reuseNameMismatch++;
			}
		}

		error.WriteLine($"reuse-site lines: {reuseLines.Count}, ShouldReuse(parsedName, linkedIngredientId) false: {reuseNameMismatch}");

		var tierLines = results.Where(r => r.Relation == AutoWrongClassifier.RelationRowChoiceTier).ToList();
		var keyHigher = tierLines.Count(r => TierRank(r.KeyTier) > TierRank(r.AcceptedTier));
		var acceptedHigher = tierLines.Count(r => TierRank(r.AcceptedTier) > TierRank(r.KeyTier));
		error.WriteLine($"row-choice-tier lines: {tierLines.Count}, key tier higher: {keyHigher}, accepted tier higher: {acceptedHigher}");

		foreach (var r in results.Where(r => r.Relation == AutoWrongClassifier.RelationSameHeadOtherQualifier))
		{
			error.WriteLine($"same-head-other-qualifier {r.HoldoutId}#{r.LineIndex}: key-only=[{string.Join(' ', r.KeyOnlyQualifiers ?? [])}] accepted-only=[{string.Join(' ', r.AcceptedOnlyQualifiers ?? [])}]");
		}
	}

	private static int TierRank(string tier) => tier.ToLowerInvariant() switch
	{
		"foundation" => 4,
		"srllegacy" => 3,
		"survey" => 2,
		"branded" => 1,
		_ => 0,
	};

	private static string First(IReadOnlyList<string> values) => values.Count > 0 ? values[0] : string.Empty;

	private static string Sanitize(string value) =>
		value.Replace('\t', ' ').Replace('\n', ' ').Replace('\r', ' ');
}
