{"content":"using System.Text.Json;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.AutoWrongCensus.Options;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Resolver;
using Microsoft.Extensions.Options;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// The census runner: reads one HoldoutGate trace, classifies every <c>auto &amp;&amp; !correct</c>
/// line, and writes the TSV to <see cref="OutputWriters.Output"/> and the relation × site summary to
/// <see cref="OutputWriters.Error"/>. Refuses any trace whose record <c>set</c> is not <c>debug</c>
/// or <c>batch</c> (D-029: no sealed read).
/// </summary>
public sealed class AutoWrongCensusRunner(
	IOptions<AutoWrongCensusOptions> options,
	AutoWrongClassifier classifier,
	OutputWriters writers) : IAutoWrongCensusRunner
{
	private static readonly JsonSerializerOptions JsonOptions = new(JsonSerializerDefaults.Web);

	private const string CensusHeader = "holdoutId\tlineIndex\tset\trelation\tsite\toverrideKey\tacceptedTier\tkeyTier\tacceptedState\tkeyState\tparsedName\tkeyHead\tacceptedDesc\tkeyDesc\trawText";

	private const string PairsHeader = "holdoutId\tlineIndex\tparsedNameHead\tkeyHead\trawText";

	/// <inheritdoc />
	public async Task<int> RunAsync(CancellationToken cancellationToken)
	{
		var opts = options.Value;
		if (opts.Command == CommandLineArgumentParser.CensusCommand)
		{
			return await RunCensusAsync(opts.TracePath, cancellationToken).ConfigureAwait(false);
		}

		if (opts.Command == CommandLineArgumentParser.PairsCommand)
		{
			return await RunPairsAsync(opts.CensusTsvPath, opts.TracePath, cancellationToken).ConfigureAwait(false);
		}

		writers.Error.WriteLine("unusable arguments; expected: census <trace.jsonl> | pairs <census.tsv> <trace.jsonl>");
		return 1;
	}

	private async Task<int> RunCensusAsync(string tracePath, CancellationToken cancellationToken)
	{
		var lines = await ReadTraceAsync(tracePath, cancellationToken).ConfigureAwait(false);
		if (lines is null)
		{
			return 1;
		}

		var refused = lines.Where(l => !IsAllowedSet(l.Set)).ToList();
		if (refused.Count > 0)
		{
			writers.Error.WriteLine($"refused: {refused.Count} record(s) with set '{refused[0].Set}' — this tool reads debug/batch traces only (D-029).");
			return 1;
		}

		var autoWrong = lines.Where(l => l.Auto && !l.Correct).ToList();
		var results = new List<ClassificationResult>(autoWrong.Count);
		var unknownSites = 0;
		foreach (var line in autoWrong)
		{
			var result = classifier.Classify(line);
			if (result.Site.Length == 0)
			{
				unknownSites++;
				continue;
			}

			results.Add(result);
		}

		if (unknownSites > 0)
		{
			writers.Error.WriteLine($"refused: {unknownSites} auto-wrong line(s) with an unknown atom path — the site vocabulary is ranker/override/curated; not classifying a partial census.");
			return 1;
		}

		writers.Output.WriteLine(CensusHeader);
		foreach (var r in results)
		{
			writers.Output.WriteLine(string.Join('\t',
				Sanitize(r.HoldoutId), r.LineIndex, Sanitize(r.Set), Sanitize(r.Relation), Sanitize(r.Site), Sanitize(r.OverrideKey),
				Sanitize(r.AcceptedTier), Sanitize(r.KeyTier), Sanitize(r.AcceptedState), Sanitize(r.KeyState),
				Sanitize(r.ParsedName), Sanitize(r.KeyHead), Sanitize(r.AcceptedDesc), Sanitize(r.KeyDesc), Sanitize(r.RawText)));
		}

		WriteSummary(results, autoWrong.Count);
		return 0;
	}

	private async Task<int> RunPairsAsync(string censusTsvPath, string tracePath, CancellationToken cancellationToken)
	{
		var lines = await ReadTraceAsync(tracePath, cancellationToken).ConfigureAwait(false);
		if (lines is null)
		{
			return 1;
		}

		var refused = lines.Where(l => !IsAllowedSet(l.Set)).ToList();
		if (refused.Count > 0)
		{
			writers.Error.WriteLine($"refused: {refused.Count} record(s) with set '{refused[0].Set}' — this tool reads debug/batch traces only (D-029).");
			return 1;
		}

		if (!File.Exists(censusTsvPath))
		{
			writers.Error.WriteLine($"census TSV not found at '{censusTsvPath}'.");
			return 1;
		}

		var wanted = new HashSet<(string HoldoutId, int LineIndex)>(StringComparer.Ordinal);
		var censusLines = File.ReadLines(censusTsvPath).ToList();
		if (censusLines.Count == 0)
		{
			writers.Error.WriteLine($"census TSV '{censusTsvPath}' is empty.");
			return 1;
		}

		var header = censusLines[0].Split('\t');
		var column = new Dictionary<string, int>(StringComparer.Ordinal);
		for (var i = 0; i < header.Length; i++)
		{
			column[header[i]] = i;
		}

		foreach (var name in new[] { "holdoutId", "lineIndex", "blocker", "route" })
		{
			if (!column.ContainsKey(name))
			{
				writers.Error.WriteLine($"census TSV '{censusTsvPath}' is missing column '{name}'.");
				return 1;
			}
		}

		foreach (var row in censusLines.Skip(1))
		{
			var cells = row.Split('\t');
			if (cells.Length < header.Length)
			{
				continue;
			}

			if (cells[column["blocker"]].Equals("window", StringComparison.Ordinal)
				&& (cells[column["route"]].Equals("compound", StringComparison.Ordinal) || cells[column["route"]].Equals("other", StringComparison.Ordinal)))
			{
				wanted.Add((cells[column["holdoutId"]], int.Parse(cells[column["lineIndex"]])));
			}
		}

		var byKey = lines.ToDictionary(l => (l.HoldoutId, l.LineIndex));
		writers.Output.WriteLine(PairsHeader);
		var emitted = 0;
		foreach (var (holdoutId, lineIndex) in wanted)
		{
			if (!byKey.TryGetValue((holdoutId, lineIndex), out var line))
			{
				writers.Error.WriteLine($"pairs: census row {holdoutId}#{lineIndex} not found in the trace; skipped.");
				continue;
			}

			var parsedNameHead = string.Join(' ', classifier.KeyHeadPhrase(_normalizerTokens(line.Atoms[0].ParsedName)));
			var keyDesc = line.ExpectedDescriptions.Count > 0 ? line.ExpectedDescriptions[0] : string.Empty;
			var keyHead = string.Join(' ', classifier.KeyHeadPhrase(_normalizerTokens(keyDesc)));
			writers.Output.WriteLine(string.Join('\t',
				Sanitize(holdoutId), lineIndex, Sanitize(parsedNameHead), Sanitize(keyHead), Sanitize(line.RawText)));
			emitted++;
		}

		writers.Error.WriteLine($"pairs: {emitted}/{wanted.Count} window compound/other rows emitted.");
		return 0;
	}

	private IReadOnlyList<TraceLine>? ReadTrace(string tracePath)
	{
		if (!File.Exists(tracePath))
		{
			writers.Error.WriteLine($"trace not found at '{tracePath}'.");
			return null;
		}

		var lines = new List<TraceLine>();
		foreach (var raw in File.ReadLines(tracePath))
		{
			if (string.IsNullOrWhiteSpace(raw))
			{
				continue;
			}

			try
			{
				lines.Add(JsonSerializer.Deserialize<TraceLine>(raw, JsonOptions)
					?? throw new InvalidOperationException("trace line deserialized to null."));
			}
			catch (JsonException ex)
			{
				writers.Error.WriteLine($"trace '{tracePath}' has an unparseable line: {ex.Message}");
				return null;
			}
		}

		return lines;
	}

	private async Task<IReadOnlyList<TraceLine>?> ReadTraceAsync(string tracePath, CancellationToken cancellationToken)
	{
		cancellationToken.ThrowIfCancellationRequested();
		return ReadTrace(tracePath);
	}

	private void WriteSummary(IReadOnlyList<ClassificationResult> results, int autoWrongCount)
	{
		var set = results.Count > 0 ? results[0].Set : string.Empty;
		writers.Error.WriteLine($"autoWrongCensus set={set} autoWrongLines={autoWrongCount} classified={results.Count}");

		var matrix = results
			.GroupBy(r => (r.Relation, r.Site))
			.Select(g => (g.Key.Relation, g.Key.Site, g.Count()))
			.OrderBy(t => t.Relation, StringComparer.Ordinal)
			.ThenBy(t => t.Site, StringComparer.Ordinal);

		writers.Error.WriteLine("relation\tsite\tcount");
		foreach (var (relation, site, count) in matrix)
		{
			writers.Error.WriteLine($"{relation}\t{site}\t{count}");
		}

		var otherCount = results.Count(r => r.Relation == AutoWrongClassifier.RelationOther);
		writers.Error.WriteLine($"other={otherCount}/{autoWrongCount} ({(autoWrongCount > 0 ? otherCount * 100.0 / autoWrongCount : 0.0):F1}%)");

		var missing = results.Where(r => r.MissingField is not null)
			.GroupBy(r => r.MissingField)
			.Select(g => $"{g.Key}={g.Count()}");
		writers.Error.WriteLine(missing.Any() ? $"missingFields: {string.Join(' ', missing)}" : "missingFields: none");

		var overrideLines = results.Where(r => r.Site == AutoWrongClassifier.SiteOverride).ToList();
		writers.Error.WriteLine($"overrideKey: yes={overrideLines.Count(r => r.OverrideKey == "yes")} no={overrideLines.Count(r => r.OverrideKey == "no")} (of {overrideLines.Count} override-site lines)");

		var reuseLines = results.Where(r => r.Site == AutoWrongClassifier.SiteReuse).ToList();
		var reuseFalse = reuseLines.Count(r =>
			!string.IsNullOrEmpty(r.ParsedName)
			&& r.ParsedName.Length > 0
			&& !ShouldReuseParsedName(r));
		writers.Error.WriteLine($"reuse-site lines where the resolver's own ShouldReuse(parsedName, linkedIngredientId) is false: {reuseFalse}/{reuseLines.Count}");

		var tierLines = results.Where(r => r.Relation == AutoWrongClassifier.RelationRowChoiceTier).ToList();
		writers.Error.WriteLine($"row-choice-tier: key higher={tierLines.Count(r => TierRank(r.KeyTier) > TierRank(r.AcceptedTier))} accepted higher={tierLines.Count(r => TierRank(r.AcceptedTier) > TierRank(r.KeyTier))} (of {tierLines.Count})");

		foreach (var r in results.Where(r => r.Relation == AutoWrongClassifier.RelationSameHeadOtherQualifier))
		{
			writers.Error.WriteLine($"qualdiff {r.HoldoutId}#{r.LineIndex}: keyOnly=[{string.Join(' ', r.KeyOnlyQualifiers ?? [])}] acceptedOnly=[{string.Join(' ', r.AcceptedOnlyQualifiers ?? [])}]");
		}
	}

	private static bool ShouldReuseParsedName(ClassificationResult r)
	{
		// The trace carries the linked master slug; the resolver's own slug computation and
		// exact-phrase reuse rule decide whether the line's name would have matched that master.
		var slug = IngredientLineParser.ComputeSlug(r.ParsedName);
		return IngredientLineResolver.ShouldReuse(slug, r.ParsedName);
	}

	private static int TierRank(string tier) => tier.ToLowerInvariant() switch
	{
		"foundation" => 4,
		"srllegacy" => 3,
		"survey" => 2,
		"branded" => 1,
		_ => 0,
	};

	private static bool IsAllowedSet(string set) =>
		set.Equals("debug", StringComparison.Ordinal) || set.Equals("batch", StringComparison.Ordinal);

	private static string Sanitize(string value) =>
		value.Replace('\t', ' ').Replace('\n', ' ').Replace('\r', ' ');

	private IReadOnlyList<string> _normalizerTokens(string text) => _normalizer.NormalizeToTokens(text);

	private readonly FdcNormalizer _normalizer;
}
